import{c as e,i as t,o as n,r,s as i,t as a}from"./app-qKiKnNug.js";var o=JSON.parse(`{"path":"/program/program/front/brower.html","title":"浏览器","lang":"zh-CN","frontmatter":{"description":"浏览器 浏览器解析 1. 请求网页 发送请求：浏览器通过 HTTP/HTTPS 协议向服务器发送请求，请求指定的网页资源。 接收响应：服务器处理请求并返回网页内容（如 HTML、CSS、JavaScript、图片等）。 2. 解析 HTML 构建 DOM 树：浏览器解析 HTML 文档，将其转换为 DOM（文档对象模型）树。DOM 树是表示网页结构的树...","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"浏览器\\",\\"image\\":[\\"\\"],\\"dateModified\\":\\"2026-03-11T05:49:26.000Z\\",\\"author\\":[{\\"@type\\":\\"Person\\",\\"name\\":\\"DeeLMind\\",\\"url\\":\\"https://deelmind.com\\"}]}"],["meta",{"property":"og:url","content":"https://deelmind.com/program/program/front/brower.html"}],["meta",{"property":"og:site_name","content":"極客方舟"}],["meta",{"property":"og:title","content":"浏览器"}],["meta",{"property":"og:description","content":"浏览器 浏览器解析 1. 请求网页 发送请求：浏览器通过 HTTP/HTTPS 协议向服务器发送请求，请求指定的网页资源。 接收响应：服务器处理请求并返回网页内容（如 HTML、CSS、JavaScript、图片等）。 2. 解析 HTML 构建 DOM 树：浏览器解析 HTML 文档，将其转换为 DOM（文档对象模型）树。DOM 树是表示网页结构的树..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2026-03-11T05:49:26.000Z"}],["meta",{"property":"article:modified_time","content":"2026-03-11T05:49:26.000Z"}]]},"git":{"createdTime":1734955114000,"updatedTime":1773208166000,"contributors":[{"name":"DeeLMind","username":"DeeLMind","email":"deelmind@gmail.com","commits":2,"url":"https://github.com/DeeLMind"}]},"readingTime":{"minutes":3.18,"words":955},"filePathRelative":"program/program/front/brower.md","autoDesc":true}`),s={name:`brower.md`};function c(a,o,s,c,l,u){let d=e(`DocsAD`);return i(),r(`div`,null,[o[0]||=t(`<h1 id="浏览器" tabindex="-1"><a class="header-anchor" href="#浏览器"><span>浏览器</span></a></h1><h2 id="浏览器解析" tabindex="-1"><a class="header-anchor" href="#浏览器解析"><span>浏览器解析</span></a></h2><h3 id="_1-请求网页" tabindex="-1"><a class="header-anchor" href="#_1-请求网页"><span>1. <strong>请求网页</strong></span></a></h3><ul><li><strong>发送请求</strong>：浏览器通过 HTTP/HTTPS 协议向服务器发送请求，请求指定的网页资源。</li><li><strong>接收响应</strong>：服务器处理请求并返回网页内容（如 HTML、CSS、JavaScript、图片等）。</li></ul><h3 id="_2-解析-html" tabindex="-1"><a class="header-anchor" href="#_2-解析-html"><span>2. <strong>解析 HTML</strong></span></a></h3><ul><li><strong>构建 DOM 树</strong>：浏览器解析 HTML 文档，将其转换为 DOM（文档对象模型）树。DOM 树是表示网页结构的树状结构，包含所有的 HTML 元素和文本节点。</li><li><strong>处理文档类型</strong>：根据文档类型声明（如<code>&lt;!DOCTYPE html&gt;</code>），确定解析模式（标准模式或怪异模式）。</li></ul><h3 id="_3-解析-css" tabindex="-1"><a class="header-anchor" href="#_3-解析-css"><span>3. <strong>解析 CSS</strong></span></a></h3><ul><li><strong>构建 CSSOM 树</strong>：浏览器解析 CSS 样式表，将其转换为 CSSOM（CSS 对象模型）树。CSSOM 树包含所有的 CSS 规则和样式信息。</li><li><strong>应用样式</strong>：将 CSSOM 树中的样式信息应用到 DOM 树上，为每个 DOM 节点计算样式。</li></ul>`,8),n(d),o[1]||=t(`<h3 id="_4-构建渲染树" tabindex="-1"><a class="header-anchor" href="#_4-构建渲染树"><span>4. <strong>构建渲染树</strong></span></a></h3><ul><li><strong>生成渲染树</strong>：结合 DOM 树和 CSSOM 树，生成渲染树。渲染树包含了需要绘制的可视化内容，排除了一些不可见的内容（如<code>display: none</code>的元素）。</li><li><strong>计算布局</strong>：为渲染树中的每个元素计算位置和大小，生成布局信息。这一过程被称为“回流”或“重排”。</li></ul><h3 id="_5-绘制" tabindex="-1"><a class="header-anchor" href="#_5-绘制"><span>5. <strong>绘制</strong></span></a></h3><ul><li><strong>绘制内容</strong>：根据布局信息，将渲染树中的元素绘制到屏幕上。这一过程将视觉效果（如颜色、边框、阴影等）应用到页面元素。</li></ul><h3 id="_6-执行-javascript" tabindex="-1"><a class="header-anchor" href="#_6-执行-javascript"><span>6. <strong>执行 JavaScript</strong></span></a></h3><ul><li><strong>解析和执行</strong>：浏览器解析并执行 JavaScript 代码。JavaScript 代码可能会修改 DOM 树、CSSOM 树，或者触发事件。</li><li><strong>更新渲染</strong>：JavaScript 修改页面内容后，可能需要重新计算布局和绘制，称为“重绘”和“重排”。</li></ul><h3 id="_7-处理异步操作" tabindex="-1"><a class="header-anchor" href="#_7-处理异步操作"><span>7. <strong>处理异步操作</strong></span></a></h3><ul><li><strong>异步加载</strong>：浏览器可以异步加载资源（如图片、脚本、样式表）以提高页面性能。</li><li><strong>事件处理</strong>：浏览器处理用户交互和事件（如点击、滚动、键盘输入），并相应地更新页面内容。</li></ul><h3 id="_8-缓存" tabindex="-1"><a class="header-anchor" href="#_8-缓存"><span>8. <strong>缓存</strong></span></a></h3><ul><li><strong>缓存机制</strong>：浏览器缓存静态资源（如 CSS、JavaScript、图片），以减少重复请求，加快页面加载速度。</li><li><strong>缓存控制</strong>：使用 HTTP 缓存头（如<code>Cache-Control</code>、<code>Expires</code>）管理缓存策略，确保最新内容的加载。</li></ul><h3 id="_9-性能优化" tabindex="-1"><a class="header-anchor" href="#_9-性能优化"><span>9. <strong>性能优化</strong></span></a></h3><ul><li><strong>优化渲染</strong>：浏览器引擎使用各种优化技术（如合成层、GPU 加速）提升页面渲染性能。</li><li><strong>异步任务</strong>：通过 Web Workers 和异步 JavaScript 操作，避免主线程阻塞，提高用户体验。</li></ul><h2 id="主流浏览器内核" tabindex="-1"><a class="header-anchor" href="#主流浏览器内核"><span>主流浏览器内核</span></a></h2><h3 id="_1-blink" tabindex="-1"><a class="header-anchor" href="#_1-blink"><span>1. Blink</span></a></h3><ul><li><strong>简介</strong>：Blink 是 Google 开发的开源渲染引擎。它是 WebKit 的一个分支。</li><li><strong>主要浏览器</strong>： <ul><li><strong>Google Chrome</strong>： <a href="https://www.google.com/chrome/" target="_blank" rel="noopener noreferrer">google.com/chrome</a></li><li><strong>Microsoft Edge</strong>（基于 Chromium）： <a href="https://www.microsoft.com/edge" target="_blank" rel="noopener noreferrer">microsoft.com/edge</a></li><li><strong>Opera</strong>： <a href="https://www.opera.com/" target="_blank" rel="noopener noreferrer">opera.com</a></li></ul></li></ul><h3 id="_2-webkit" tabindex="-1"><a class="header-anchor" href="#_2-webkit"><span>2. WebKit</span></a></h3><ul><li><strong>简介</strong>：WebKit 是 Apple 开发的开源渲染引擎，最初由 KDE 项目开发。</li><li><strong>主要浏览器</strong>： <ul><li><strong>Safari</strong>： <a href="https://www.apple.com/safari/" target="_blank" rel="noopener noreferrer">apple.com/safari</a></li><li><strong>旧版 Android 浏览器</strong>：（部分 Android 版本中使用）</li></ul></li></ul><h3 id="_3-gecko" tabindex="-1"><a class="header-anchor" href="#_3-gecko"><span>3. Gecko</span></a></h3><ul><li><strong>简介</strong>：Gecko 是 Mozilla 开发的开源渲染引擎。</li><li><strong>主要浏览器</strong>： <ul><li><strong>Mozilla Firefox</strong>： <a href="https://www.mozilla.org/firefox/" target="_blank" rel="noopener noreferrer">mozilla.org/firefox</a></li><li><strong>Thunderbird</strong>（Mozilla 的邮件客户端）： <a href="https://www.mozilla.org/thunderbird/" target="_blank" rel="noopener noreferrer">mozilla.org/thunderbird</a></li></ul></li></ul><h3 id="_4-trident" tabindex="-1"><a class="header-anchor" href="#_4-trident"><span>4. Trident</span></a></h3><ul><li><strong>简介</strong>：Trident 是 Microsoft 开发的渲染引擎，用于旧版 Internet Explorer 浏览器。</li><li><strong>主要浏览器</strong>： <ul><li><strong>Internet Explorer</strong>： <a href="https://support.microsoft.com/internet-explorer" target="_blank" rel="noopener noreferrer">support.microsoft.com/internet-explorer</a></li></ul></li></ul><h3 id="_5-edgehtml" tabindex="-1"><a class="header-anchor" href="#_5-edgehtml"><span>5. EdgeHTML</span></a></h3><ul><li><strong>简介</strong>：EdgeHTML 是 Microsoft 为新版 Edge 浏览器开发的渲染引擎，已被 Blink 替代。</li><li><strong>主要浏览器</strong>： <ul><li><strong>旧版 Microsoft Edge</strong>： <a href="https://www.microsoft.com/edge" target="_blank" rel="noopener noreferrer">microsoft.com/edge</a></li></ul></li></ul><h3 id="_6-presto" tabindex="-1"><a class="header-anchor" href="#_6-presto"><span>6. Presto</span></a></h3><ul><li><strong>简介</strong>：Presto 是 Opera Software 开发的渲染引擎，已被 Blink 替代。</li><li><strong>主要浏览器</strong>： <ul><li><strong>旧版 Opera 浏览器</strong>： <a href="https://www.opera.com/" target="_blank" rel="noopener noreferrer">opera.com</a></li></ul></li></ul><h3 id="_7-servo" tabindex="-1"><a class="header-anchor" href="#_7-servo"><span>7. Servo</span></a></h3><ul><li><strong>简介</strong>：Servo 是 Mozilla 和多家机构合作开发的实验性渲染引擎，采用 Rust 编程语言编写。</li><li><strong>主要浏览器</strong>： <ul><li><strong>目前没有主流浏览器使用</strong>，但作为实验性项目正在开发中： <a href="https://servo.org/" target="_blank" rel="noopener noreferrer">servo.org</a></li></ul></li></ul>`,27)])}var l=a(s,[[`render`,c]]);export{o as _pageData,l as default};